const $=s=>document.querySelector(s),params=new URLSearchParams(location.search),snapshot=params.has('shot');if(snapshot)document.body.classList.add('snapshot');
const foodImg=n=>'assets/food/'+n;
const meals=[{id:0,name:'西兰花豆腐暖碗',image:'p22-2.webp',time:15,theme:'西兰花绿',price:18,desc:'温热谷物与清爽蔬菜，给忙碌的一天留一点松弛。',items:[['西兰花','150 g'],['豆腐','100 g'],['熟杂粮饭','1 碗'],['胡萝卜','半根']]},{id:1,name:'牛油果彩蔬碗',image:'p22-3.webp',time:10,theme:'牛油果绿',price:22,desc:'清新的绿色与丰富口感，不开火也能轻松搭配。',items:[['牛油果','半个'],['生菜','80 g'],['熟鹰嘴豆','100 g'],['全麦面包','2 片']]},{id:2,name:'当季蔬菜便当',image:'p2-4.webp',time:20,theme:'西兰花绿',price:25,desc:'把喜欢的蔬菜装进便当，给明天提前留一份期待。',items:[['西兰花','100 g'],['小番茄','6 个'],['鸡蛋','1 个'],['熟杂粮饭','1 碗']]},{id:3,name:'谷物暖心拼盘',image:'p29-4.webp',time:15,theme:'谷物金',price:20,desc:'熟悉的谷物与当季食材，搭配成温暖的一餐。',items:[['玉米','半根'],['豆腐','100 g'],['熟杂粮饭','1 碗'],['绿叶菜','100 g']]}];
let data={saved:[],list:[],meal:0,servings:1,mood:'今天，也有好好吃饭。',swapped:false};try{if(!snapshot)data={...data,...JSON.parse(localStorage.getItem('food-pantone-demo')||'{}')}}catch{}let page=params.get('screen')||'home',filter='全部',selected=data.meal||0;
if(snapshot){data={...data,saved:[0,1],meal:0,list:meals[0].items.map((x,i)=>({name:x[0],qty:x[1],done:i===0})),servings:1}}
function persist(){if(!snapshot)try{localStorage.setItem('food-pantone-demo',JSON.stringify(data))}catch{}}
let toastTimer;function toast(t){$('.toast').textContent=t;$('.toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('.toast').hidden=true,2400)}
function go(p){page=p;render();window.scrollTo(0,0)}
const ico=[`<path d="M3 10L12 3l9 7v11h-6v-7H9v7H3z"/>`,`<rect x="3" y="3" width="7" height="7" rx="2"/><rect x="14" y="3" width="7" height="7" rx="2"/><rect x="3" y="14" width="7" height="7" rx="2"/><rect x="14" y="14" width="7" height="7" rx="2"/>`,`<path d="M7 4h10v3H7zM5 5H3v17h18V5h-2M7 12h10M7 17h7"/>`,`<path d="M4 4h16v17H4zM4 15h16"/><circle cx="12" cy="9" r="3"/>`];
function nav(){const current=page==='home'||page==='palette'?'home':page==='meals'||page==='detail'?'meals':page==='list'||page==='empty'?'list':'saved';$('#app-nav').innerHTML=['home','meals','list','saved'].map((p,i)=>`<button data-go="${p}" class="${current===p?'active':''}" aria-label="${['发现','搭配','清单','色卡'][i]}"><svg viewBox="0 0 24 24">${ico[i]}</svg>${['发现','搭配','清单','色卡'][i]}${p==='list'&&data.list.length?`<b>${data.list.length}</b>`:''}</button>`).join('')}
function back(title,to='home'){return `<div class="app-heading"><button class="toplink" data-go="${to}" aria-label="返回">‹</button><h2>${title}</h2><span style="width:33px"></span></div>`}
function item(m,grid=false){return `<button ${grid?'':`class="meal-card"`} data-meal="${m.id}"><img src="${foodImg(m.image)}" alt="${m.name}示意"><div><h3>${m.name}</h3><p>${m.time} 分钟 · 1 人份 · ${m.theme}</p>${grid?`<strong>约 ¥${m.price} / 份</strong>`:`<span class="pill">看看这一餐 ↗</span>`}</div></button>`}
function render(){document.body.dataset.page=page;nav();let h='';const m=meals[selected];
if(page==='welcome')h=`<div class="welcome"><div class="app-heading"><span class="brand-word">FOOD PANTONE®</span><button class="skip" data-go="home">跳过</button></div><div class="welcome-art"><img src="${foodImg('p1-0.webp')}" alt="手捧彩色餐碗"></div><div class="welcome-copy"><small>COLOUR YOUR EVERYDAY</small><h1>喜欢的颜色，<br>也可以是今天的一餐。</h1><p>发现当季食材，找到简单搭配。<br>让好好吃饭，从一点喜欢开始。</p><button class="primary" data-go="home">开始我的食色之旅 →</button><p class="small-note">无需注册 · 自由探索</p></div></div>`;
else if(page==='home')h=`<header class="app-heading"><div><small>FOOD PANTONE®</small><h1>今天，吃点新鲜的。</h1></div><button class="avatar" data-go="saved" aria-label="我的色卡"><img src="assets/food/food-logo.svg" alt="食色"></button></header><button class="search" data-go="meals"><b>⌕</b>找一道喜欢的菜，或一种颜色 <span style="margin-left:auto">↗</span></button><section class="season-card"><small>THE SEASONAL EDIT / VOL. 01</small><h2>Broccoli<br>Green<span>这一季，西兰花绿。</span></h2><img src="${foodImg('p8-2.webp')}" alt="西兰花"><div class="dots"><i></i><i></i><i></i></div><div class="season-foot"><p>把一抹绿色，带到餐桌。<br>探索食材背后的色彩灵感</p><button class="round-go" data-go="palette" aria-label="探索当季颜色">↗</button></div></section><div class="section-label"><h2>为今天，搭配一餐</h2><button data-go="meals">全部搭配 ↗</button></div>${item(meals[0])}<div class="section-label"><h2>色彩，也是生活灵感</h2></div><button class="palette-teaser" data-go="palette" style="width:100%;text-align:left"><div><h3>收藏你的当季色</h3><p>食物 × 风格 × 每一天</p></div><div class="color-circles"><i></i><i></i><i></i></div></button>`;
else if(page==='palette')h=back('当季色彩')+`<h1>从餐桌，<br>发现生活的调色盘。</h1><p class="screen-sub">颜色是灵感，搭配由你决定。</p><div class="palette-list">${[['#168360','BROCCOLI GREEN','西兰花绿','p8-2.webp','清新日常，从一份温热蔬菜开始。'],['#bccda1','AVOCADO GREEN','牛油果绿','p8-2.webp','给忙碌的日常，一点柔和的留白。'],['#e7d67b','GRAIN GOLD','谷物金','p8-3.webp','温暖而熟悉，是喜欢的一餐。']].map((a,i)=>`<button class="palette-block" style="--c:${a[0]}" data-theme="${i}"><small>${a[1]}</small><h2>${a[2]} ↗</h2><p>${a[4]}</p>${i===0?`<img src="${foodImg(a[3])}" alt="西兰花">`:''}</button>`).join('')}</div><p class="small-note">主题色用于灵感探索，不代表营养评分。</p>`;
else if(page==='meals'){const filtered=filter==='全部'?meals:filter==='10 分钟'?meals.filter(x=>x.time<=10):filter==='15 分钟'?meals.filter(x=>x.time<=15):meals.filter(x=>x.theme===filter);h=`<div class="app-heading"><div><small>MAKE IT EASY</small><h1>一餐，不用想太多。</h1></div><button class="toplink" data-go="home" aria-label="返回首页">‹</button></div><p class="screen-sub">选一个适合今天的节奏。</p><div class="theme-banner"><div><h2>小小改变，也很新鲜。</h2><p>把当季颜色，搭配成你喜欢的一餐。</p></div><img src="${foodImg('p8-2.webp')}" alt="西兰花"></div><div class="filters" aria-label="餐食筛选">${['全部','10 分钟','15 分钟','西兰花绿'].map(x=>`<button data-filter="${x}" class="${filter===x?'selected':''}">${x}</button>`).join('')}</div><div class="food-grid">${filtered.map(x=>item(x,true)).join('')}</div><p class="small-note">时间、价格为概念示例；图片用于展示搭配氛围。</p>`}
else if(page==='detail')h=back('今天的一餐','meals')+`<img class="meal-hero" src="${foodImg(m.image)}" alt="${m.name}搭配示意"><div class="detail-title"><div><small>${m.theme.toUpperCase()} / DAILY BOWL</small><h1>${m.name}</h1></div><button class="save-button" data-action="save" aria-label="${data.saved.includes(m.id)?'取消收藏':'收藏餐食'}">${data.saved.includes(m.id)?'♥':'♡'}</button></div><p style="margin-top:9px">${m.desc}</p><div class="stats"><div>${m.time}<span>分钟 · 示例</span></div><div>1<span>人份</span></div><div>¥${m.price}<span>参考食材费用</span></div></div><div class="section-label" style="margin:12px 0 4px"><h2>准备这些就好</h2><small>4 种食材</small></div>${m.items.map((x,i)=>`<div class="ingredient"><span>${i===1&&data.swapped?'熟鹰嘴豆':x[0]}</span><small>${x[1]}</small>${i===1?'<button data-action="swap">换一种 ↻</button>':''}</div>`).join('')}<div class="instruction">① 清洗并处理食材　② 按各食材需要烹熟<br>③ 与熟谷物搭配，按喜好调味。</div><div class="detail-footer"><button class="primary" data-action="add">加入这一餐的食材清单 ＋</button></div>`;
else if(page==='empty'||page==='list'&&!data.list.length)h=back('我的食材清单')+`<div class="empty"><div class="empty-symbol">＋</div><h2>下一餐，还留着空白。</h2><p>发现一道喜欢的搭配，<br>食材就会整齐地出现在这里。</p><button class="primary" data-go="meals">去选一餐 →</button></div>`;
else if(page==='list'){let done=data.list.filter(x=>x.done).length;h=`<div class="app-heading"><div><small>MY SHOPPING LIST</small><h1>让准备，简单一点。</h1></div><button class="toplink" data-go="meals" aria-label="增加餐食">＋</button></div><section class="list-summary"><div><h2>${meals[data.meal].name}</h2><p>食材清单 · 已准备 ${done} / ${data.list.length}</p></div><strong>${done}<small>/${data.list.length}</small></strong></section><div class="list-top"><h2>需要准备</h2><div class="servings"><button data-action="minus" aria-label="减少份数">−</button>${data.servings} 人份<button data-action="plus" aria-label="增加份数">＋</button></div></div>${data.list.map((x,i)=>`<label class="list-row ${x.done?'checked':''}"><input type="checkbox" data-check="${i}" ${x.done?'checked':''}><span>${x.name}</span><small>${x.qty}${data.servings>1?' × '+data.servings:''}</small></label>`).join('')}<div class="shopping-info"><div><h3>食材参考费用</h3><p>非商家实时报价</p></div><strong>约 ¥${meals[data.meal].price*data.servings}</strong></div><button class="primary" data-action="finish">${done===data.list.length?'都准备好了，留下色卡 →':'记录这一次搭配 →'}</button><button class="secondary" data-action="clear">清空本餐清单</button><p class="small-note">清单仅保存在当前浏览器。原型不提供采购或支付。</p>`}
else if(page==='card')h=back('我的今日色卡','saved')+`<p class="screen-sub">留下一点新鲜，不必追求完美。</p><article class="colour-card"><div class="swatch-block"><h2>EAT<br>THE<br>TREND.</h2><img src="${foodImg('p8-2.webp')}" alt="西兰花"></div><div class="card-caption"><div><h3>FOOD PANTONE®</h3><p>西兰花绿 / MY DAILY COLOUR</p><p id="mood-preview"></p></div><b>01</b></div></article><label for="mood" class="screen-sub">为今天留一句话</label><input class="mood-input" id="mood" maxlength="35" placeholder="今天，也有好好吃饭。"><button class="primary" data-action="download">下载我的色卡 ↓</button><p class="card-note">保存为 SVG 图片 · 分享由你决定</p>`;
else if(page==='saved')h=`<header class="app-heading"><div><small>MY COLOUR COLLECTION</small><h1>我的生活，有点色彩。</h1></div><span class="avatar"><img src="assets/food/food-logo.svg" alt="食色"></span></header><div class="profile-band"><h2>每一次尝试，都值得留下。</h2><p>不比较，不排名。记录属于自己的节奏。</p><button class="primary" data-go="card" style="margin-top:16px">制作今日色卡 ↗</button></div><div class="section-label"><h2>收藏的一餐</h2><small>${data.saved.length} 份灵感</small></div>${data.saved.length?data.saved.map(id=>item(meals[id])).join(''):'<div class="saved-empty"><p>喜欢的搭配，点击心形就能收藏。</p><button data-go="meals">去发现一餐 ↗</button></div>'}<div class="section-label"><h2>当季色彩</h2><button data-go="palette">探索 ↗</button></div><div class="palette-teaser"><p>西兰花绿 · 牛油果绿 · 谷物金</p><div class="color-circles"><i></i><i></i><i></i></div></div><p class="small-note">Food Pantone 数字体验概念<br>基于饮食文化研究延展 · 示例内容未经过营养评估</p>`;
else{page='home';return render()}$('#screen').innerHTML=h;if(page==='card'){$('#mood').value=data.mood;$('#mood-preview').textContent=data.mood}}
document.addEventListener('click',e=>{const b=e.target.closest('button,[data-go]');if(!b)return;if(b.dataset.go){if(b.dataset.go==='meals')filter='全部';return go(b.dataset.go)}if(b.dataset.meal!==undefined){selected=Number(b.dataset.meal);data.swapped=false;return go('detail')}if(b.dataset.filter){filter=b.dataset.filter;return render()}if(b.dataset.theme!==undefined){filter=['西兰花绿','牛油果绿','谷物金'][Number(b.dataset.theme)];return go('meals')}const a=b.dataset.action;if(a==='save'){data.saved=data.saved.includes(selected)?data.saved.filter(x=>x!==selected):[...data.saved,selected];persist();render();toast(data.saved.includes(selected)?'已收藏这一餐':'已取消收藏')}if(a==='swap'){data.swapped=!data.swapped;render();toast(data.swapped?'已替换为熟鹰嘴豆':'已恢复原食材')}if(a==='add'){data.meal=selected;data.servings=1;data.list=meals[selected].items.map((x,i)=>({name:i===1&&data.swapped?'熟鹰嘴豆':x[0],qty:x[1],done:false}));persist();go('list');toast('这一餐的 4 种食材已加入清单')}if(a==='plus'||a==='minus'){data.servings=Math.max(1,Math.min(6,data.servings+(a==='plus'?1:-1)));persist();render()}if(a==='clear'){data.list=[];persist();render();toast('本餐清单已清空')}if(a==='finish')go('card');if(a==='download')downloadCard()});
document.addEventListener('change',e=>{if(e.target.dataset.check!==undefined){data.list[Number(e.target.dataset.check)].done=e.target.checked;persist();render()}});document.addEventListener('input',e=>{if(e.target.id==='mood'){data.mood=e.target.value;$('#mood-preview').textContent=data.mood;persist()}});
function downloadCard(){const esc=s=>s.replace(/[<>&"']/g,c=>({'<':'&lt;','>':'&gt;','&':'&amp;','"':'&quot;',"'":'&apos;'}[c]));const svg=`<svg xmlns="http://www.w3.org/2000/svg" width="900" height="1200"><rect width="900" height="1200" fill="#fcfdf8"/><rect width="900" height="860" fill="#acc591"/><g font-family="Arial,Microsoft YaHei,sans-serif"><text x="70" y="190" font-size="120" font-weight="bold" fill="#f6faec">EAT</text><text x="70" y="330" font-size="120" font-weight="bold" fill="#f6faec">THE TREND.</text><circle cx="640" cy="650" r="130" fill="#638747"/><circle cx="560" cy="565" r="110" fill="#779956"/><circle cx="720" cy="540" r="105" fill="#54763c"/><path d="M640 830L595 650L675 650Z" fill="#d5e4bd"/><text x="70" y="965" font-size="54" font-weight="bold" fill="#345f39">FOOD PANTONE®</text><text x="70" y="1030" font-size="28" fill="#69835a">西兰花绿 / MY DAILY COLOUR</text><text x="70" y="1110" font-size="${data.mood.length>22?21:28}" fill="#69835a">${esc(data.mood)}</text></g></svg>`;const url=URL.createObjectURL(new Blob([svg],{type:'image/svg+xml;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='Food-Pantone-我的色卡.svg';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('色卡已生成，开始下载')}
render();
